1	import jsonata from 'jsonata';
2	import { ExpressionError } from './errors.js';
3	import { unsafeRegexReason } from './regex-safety.js';
4	
5	type Compiled = ReturnType<typeof jsonata>;
6	
7	const cache = new Map<string, Compiled>();
8	const CACHE_LIMIT = 512;
9	
10	export interface ExpressionOptions {
11	  /** Wall-clock limit for one evaluation. */
12	  timeoutMs?: number;
13	  /** Maximum recursion depth of the evaluator. */
14	  maxDepth?: number;
15	  /** Extra bindings available as `$name`. */
16	  bindings?: Record<string, unknown>;
17	}
18	
19	/** jsonata throws plain objects with a `message`, not Error instances. */
20	function describeError(error: unknown): string {
21	  if (error instanceof Error) return error.message;
22	  if (typeof error === 'object' && error !== null && 'message' in error) {
23	    return String(error.message);
24	  }
25	  return String(error);
26	}
27	
28	/**
29	 * The first regex literal in a parsed expression that fails the static safety check. JSONata has
30	 * no way to build a regex from a string, so literals are the only regexes an expression can run;
31	 * a native regex never returns to the evaluator's hooks, so the time budget cannot stop it
32	 * (ADV-007).
33	 */
34	function unsafeRegexIn(
35	  node: unknown,
36	  seen = new Set<object>(),
37	): { source: string; reason: string } | undefined {
38	  if (typeof node !== 'object' || node === null || seen.has(node)) return undefined;
39	  seen.add(node);
40	  if (node instanceof RegExp) {
41	    const reason = unsafeRegexReason(node.source, node.flags);
42	    return reason ? { source: node.source, reason } : undefined;
43	  }
44	  for (const value of Object.values(node)) {
45	    const found = unsafeRegexIn(value, seen);
46	    if (found) return found;
47	  }
48	  return undefined;
49	}
50	
51	/** Compile and check an expression. `cached: false` gives a private instance (for `$eval`). */
52	function compile(
53	  expression: string,
54	  cached = true,
55	  failed?: (reason: 'compile' | 'unsafe-regex') => void,
56	): Compiled {
57	  const hit = cached ? cache.get(expression) : undefined;
58	  if (hit) return hit;
59	  let compiled: Compiled;
60	  try {
61	    compiled = jsonata(expression);
62	  } catch (error) {
63	    failed?.('compile');
64	    throw new ExpressionError(`expression failed to compile: ${describeError(error)}`, {
65	      expression,
66	    });
67	  }
68	  const unsafe = unsafeRegexIn(compiled.ast());
69	  if (unsafe) {
70	    failed?.('unsafe-regex');
71	    throw new ExpressionError(
72	      `expression uses the regular expression /${unsafe.source}/, which can run without bound: ${unsafe.reason}`,
73	      { expression },
74	    );
75	  }
76	  if (!cached) return compiled;
77	  if (cache.size >= CACHE_LIMIT) {
78	    const first = cache.keys().next().value;
79	    if (first !== undefined) cache.delete(first);
80	  }
81	  cache.set(expression, compiled);
82	  return compiled;
83	}
84	
85	/** A JSONata native function value, as `$eval` evaluates to. */
86	interface JsonataFunction {
87	  _jsonata_function: true;
88	  implementation: (this: unknown, ...args: unknown[]) => unknown;
89	  signature?: unknown;
90	}
91	
92	let builtinEval: Promise<JsonataFunction> | undefined;
93	
94	/**
95	 * JSONata's `$eval` compiles a string at run time, which would bypass the regex check above. It
96	 * is shadowed by this binding: the string is first compiled through the same checks (an unsafe
97	 * regex or a syntax error throws), then handed to JSONata's own `$eval` implementation. That runs
98	 * in the caller's environment, so lexical variables and functions stay visible and the nested
99	 * evaluation shares the caller's depth and deadline budget (the hooks live in that environment).
100	 */
101	const CHECKED_EVAL: JsonataFunction = {
102	  _jsonata_function: true,
103	  async implementation(this: unknown, source: unknown, focus?: unknown): Promise<unknown> {
104	    if (typeof source === 'string') compile(source, false);
105	    builtinEval ??= jsonata('$eval').evaluate({}) as Promise<JsonataFunction>;
106	    const builtin = await builtinEval;
107	    try {
108	      return await builtin.implementation.apply(this, [source, focus]);
109	    } catch (error) {
110	      // JSONata's $eval wraps a failure in a new error that embeds the inner message; nested
111	      // evals would grow it exponentially. Normalise at every boundary: keep the innermost
112	      // cause, and bound the message.
113	      throw normaliseEvalError(error);
114	    }
115	  },
116	};
117	
118	/** Longest error message an expression failure carries. */
119	const MAX_ERROR_MESSAGE = 1000;
120	
121	function bounded(message: string): string {
122	  return message.length > MAX_ERROR_MESSAGE
123	    ? `${message.slice(0, MAX_ERROR_MESSAGE)}… (${message.length - MAX_ERROR_MESSAGE} more characters)`
124	    : message;
125	}
126	
127	/** The single, bounded error a failed nested `$eval` reports: its innermost cause. */
128	function normaliseEvalError(error: unknown): ExpressionError {
129	  let cause = error;
130	  while (
131	    !(cause instanceof ExpressionError) &&
132	    typeof cause === 'object' &&
133	    cause !== null &&
134	    'error' in cause &&
135	    cause.error !== undefined
136	  ) {
137	    cause = cause.error;
138	  }
139	  if (cause instanceof ExpressionError) return cause;
140	  return new ExpressionError(`$eval failed: ${bounded(describeError(cause))}`);
141	}
142	
143	export type ExpressionReason =
144	  'compile' | 'unsafe-regex' | 'depth' | 'time' | 'evaluation-rejected';
145	
146	export type ExpressionObservation<T> =
147	  { ok: true; value: T } | { ok: false; error: unknown; reason?: ExpressionReason };
148	
149	function legacyError(error: unknown, expression: string): ExpressionError {
150	  return error instanceof ExpressionError
151	    ? error
152	    : new ExpressionError(`expression failed: ${bounded(describeError(error))}`, { expression });
153	}
154	
155	/** Only a concrete invocation can produce a reason. Preparing bindings has no such evidence. */
156	export async function observeExpression(
157	  expression: string,
158	  input: unknown,
159	  options: ExpressionOptions = {},
160	): Promise<ExpressionObservation<unknown>> {
161	  let compileReason: 'compile' | 'unsafe-regex' | undefined;
162	  let expr: Compiled;
163	  try {
164	    expr = compile(expression, true, (reason) => {
165	      compileReason = reason;
166	    });
167	  } catch (error) {
168	    return { ok: false, error, ...(compileReason ? { reason: compileReason } : {}) };
169	  }
170	  let limit: { error: ExpressionError; reason: 'time' | 'depth' } | undefined;
171	  let bindings: Record<string, unknown>;
172	  try {
173	    bindings = {
174	      ...options.bindings,
175	      eval: CHECKED_EVAL,
176	      ...evaluationHooks(options.timeoutMs ?? 2000, options.maxDepth ?? 200, (error, reason) => {
177	        limit = { error, reason };
178	      }),
179	    };
180	  } catch (error) {
181	    return { ok: false, error: legacyError(error, expression) };
182	  }
183	  try {
184	    const value: unknown = await expr.evaluate(input, bindings);
185	    return { ok: true, value };
186	  } catch (error) {
187	    return {
188	      ok: false,
189	      error: legacyError(error, expression),
190	      reason: limit && limit.error === error ? limit.reason : 'evaluation-rejected',
191	    };
192	  }
193	}
194	
195	/**
196	 * Count nested calls and check elapsed time in one invocation, including checked $eval.
197	 * The pinned JSONata patch binds the hooks in that invocation's frame and finishes
198	 * sibling evaluations before starting the next.
199	 */
200	const ENTRY_HOOK = Symbol.for('jsonata.__evaluate_entry');
201	const EXIT_HOOK = Symbol.for('jsonata.__evaluate_exit');
202	
203	function evaluationHooks(
204	  timeoutMs: number,
205	  maxDepth: number,
206	  onLimit: (error: ExpressionError, reason: 'depth' | 'time') => void,
207	): Record<symbol, () => void> {
208	  let depth = 0;
209	  const start = Date.now();
210	  const check = (): void => {
211	    if (depth > maxDepth) {
212	      const error = new ExpressionError(`expression exceeded max depth ${maxDepth}`);
213	      onLimit(error, 'depth');
214	      throw error;
215	    }
216	    if (Date.now() - start > timeoutMs) {
217	      const error = new ExpressionError(`expression exceeded ${timeoutMs}ms`);
218	      onLimit(error, 'time');
219	      throw error;
220	    }
221	  };
222	  return {
223	    [ENTRY_HOOK]: () => {
224	      depth += 1;
225	      check();
226	    },
227	    [EXIT_HOOK]: () => {
228	      depth -= 1;
229	      check();
230	    },
231	  };
232	}
233	
234	/** Evaluate a JSONata expression against an input. Undefined results become `undefined`. */
235	export async function evaluateExpression(
236	  expression: string,
237	  input: unknown,
238	  options: ExpressionOptions = {},
239	): Promise<unknown> {
240	  const result = await observeExpression(expression, input, options);
241	  if (!result.ok) throw result.error;
242	  return result.value;
243	}
244	
245	/** Predicate coercion: missing/null are false, nonempty collections pass, scalars use Boolean. */
246	export async function evaluatePredicate(
247	  expression: string,
248	  input: unknown,
249	  options: ExpressionOptions = {},
250	): Promise<boolean> {
251	  const result = await observePredicate(expression, input, options);
252	  if (!result.ok) throw result.error;
253	  return result.value;
254	}
255	
256	export async function observePredicate(
257	  expression: string,
258	  input: unknown,
