1	import type {
2	  ContextThread,
3	  JsonPatch,
4	  JsonValue,
5	  Message,
6	  MessageRole,
7	  MutationOperation,
8	  PatchOperation,
9	  RepairPolicy,
10	  JsonSchema,
11	} from '@graphgoblin/contracts';
12	import { MutationError, PatchError } from './errors.js';
13	import {
14	  observeExpression,
15	  observePredicate,
16	  type ExpressionObservation,
17	  type ExpressionReason,
18	} from './expression.js';
19	import { validateJson } from './json-schema.js';
20	import { applyPatch, assertMutablePath } from './patch.js';
21	import { getAtPointer } from './pointer.js';
22	import { unsafeRegexReason } from './regex-safety.js';
23	import { observeTemplate, type TemplateFact } from './template.js';
24	import { estimateMessageTokens, threadView } from './thread-view.js';
25	
26	export interface MutationContext {
27	  /** Node performing the mutation; stamped on created messages. */
28	  nodeId: string;
29	  /** Deterministic id source for created messages. */
30	  newId: () => string;
31	  /** Deterministic clock. */
32	  now: () => string;
33	}
34	
35	/** A coerce operation whose value failed validation and may be repaired by the engine. */
36	export interface RepairRequest {
37	  opIndex: number;
38	  source: string;
39	  target: string;
40	  jsonSchema: JsonSchema;
41	  repair: RepairPolicy;
42	  value: unknown;
43	  errors: string[];
44	}
45	
46	export type MutationPlan =
47	  { kind: 'patch'; patch: JsonPatch } | { kind: 'repair'; request: RepairRequest };
48	
49	/** Optional error mapping for callers that report authored operation failures. */
50	export type MutationFailureMapper = (
51	  error: unknown,
52	  index: number,
53	  operation: MutationOperation['op'],
54	) => unknown;
55	
56	export type MutationFact =
57	  | { kind: 'expression'; reason: ExpressionReason; itemIndex?: number }
58	  | { kind: 'template'; fact: TemplateFact; itemIndex?: number }
59	  | { kind: 'regex' | 'target' | 'patch' | 'schema' };
60	
61	export type MutationFactMapper = (
62	  fact: MutationFact,
63	  index: number,
64	  operation: MutationOperation['op'],
65	) => unknown;
66	
67	type Rethrow = (error: unknown, fact?: MutationFact) => never;
68	
69	function authored<T>(operation: () => T, rethrow: Rethrow, kind: 'target' | 'regex' | 'schema'): T {
70	  try {
71	    return operation();
72	  } catch (error) {
73	    return rethrow(
74	      error,
75	      error instanceof MutationError || error instanceof PatchError ? { kind } : undefined,
76	    );
77	  }
78	}
79	
80	async function renderValue(
81	  source: string,
82	  view: Record<string, unknown>,
83	  rethrow: Rethrow,
84	  itemIndex?: number,
85	) {
86	  const result = await observeTemplate(source, view);
87	  return result.ok
88	    ? result.value
89	    : rethrow(result.error, {
90	        kind: 'template',
91	        fact: result.fact,
92	        ...(itemIndex === undefined ? {} : { itemIndex }),
93	      });
94	}
95	
96	function evaluated<T>(result: ExpressionObservation<T>, rethrow: Rethrow, itemIndex?: number): T {
97	  if (result.ok) return result.value;
98	  return rethrow(
99	    result.error,
100	    result.reason
101	      ? {
102	          kind: 'expression',
103	          reason: result.reason,
104	          ...(itemIndex === undefined ? {} : { itemIndex }),
105	        }
106	      : undefined,
107	  );
108	}
109	
110	export interface MutationResult {
111	  thread: ContextThread;
112	  patch: JsonPatch;
113	  /** Set when a coerce operation needs the engine to repair before continuing. */
114	  pending?: RepairRequest;
115	  /** Index of the first operation not yet applied (equals ops.length when complete). */
116	  appliedThrough: number;
117	}
118	
119	function asJson(value: unknown): JsonValue {
120	  if (value === undefined) return null;
121	  return JSON.parse(JSON.stringify(value)) as JsonValue;
122	}
123	
124	/** Messages built by makeMessage never contain undefined; this only satisfies the JSON type. */
125	function messageJson(message: Message): JsonValue {
126	  return message as unknown as JsonValue;
127	}
128	
129	async function resolveValue(
130	  source: Extract<MutationOperation, { op: 'set' }>['value'],
131	  view: Record<string, unknown>,
132	  rethrow: Rethrow,
133	): Promise<JsonValue> {
134	  switch (source.kind) {
135	    case 'literal':
136	      return source.value;
137	    case 'template':
138	      return renderValue(source.template, view, rethrow);
139	    case 'expression':
140	      return asJson(
141	        evaluated(await observeExpression(source.jsonata, view).catch(rethrow), rethrow),
142	      );
143	  }
144	}
145	
146	function makeMessage(
147	  ctx: MutationContext,
148	  role: MessageRole,
149	  content: string,
150	  tags: string[] | undefined,
151	): Message {
152	  return {
153	    id: ctx.newId(),
154	    role,
155	    content,
156	    nodeId: ctx.nodeId,
157	    ts: ctx.now(),
158	    ...(tags ? { tags } : {}),
159	  };
160	}
161	
162	async function selectIndices(
163	  items: readonly unknown[],
164	  where: string,
165	  view: Record<string, unknown>,
166	  rethrow: Rethrow,
167	): Promise<number[]> {
168	  const out: number[] = [];
169	  for (const [index, item] of items.entries()) {
170	    const result = await observePredicate(where, item, { bindings: { thread: view, index } }).catch(
171	      rethrow,
172	    );
173	    if (evaluated(result, rethrow, index)) out.push(index);
174	  }
175	  return out;
176	}
177	
178	function removeIndices(base: string, indices: number[]): PatchOperation[] {
179	  return [...indices].sort((a, b) => b - a).map((i) => ({ op: 'remove', path: `${base}/${i}` }));
180	}
181	
182	function replaceInString(text: string, re: RegExp, replacement: string): string {
183	  return text.replace(re, replacement);
184	}
185	
186	function walkStrings(value: unknown, fn: (s: string) => string): unknown {
187	  if (typeof value === 'string') return fn(value);
188	  if (Array.isArray(value)) return value.map((v) => walkStrings(v, fn));
189	  if (value && typeof value === 'object') {
190	    const out: Record<string, unknown> = {};
191	    for (const [k, v] of Object.entries(value as Record<string, unknown>))
192	      out[k] = walkStrings(v, fn);
193	    return out;
194	  }
195	  return value;
196	}
197	
198	function compileRegex(pattern: string, flags: string): RegExp {
199	  let re: RegExp;
200	  try {
201	    re = new RegExp(pattern, flags.includes('g') ? flags : `${flags}g`);
202	  } catch (error) {
203	    throw new MutationError(
204	      `invalid pattern "${pattern}": ${error instanceof Error ? error.message : String(error)}`,
205	    );
206	  }
207	  // The same static check as JSONata regex literals: a native match cannot be interrupted.
208	  const unsafe = unsafeRegexReason(re.source, re.flags);
209	  if (unsafe) throw new MutationError(`pattern "${pattern}" can run without bound: ${unsafe}`);
210	  return re;
211	}
212	
213	/** Plan a single operation as a patch against the given thread, without applying it. */
214	export async function planMutation(
215	  thread: ContextThread,
216	  op: MutationOperation,
217	  ctx: MutationContext,
218	  opIndex = 0,
219	  mapFailure?: MutationFailureMapper,
220	  mapFact?: MutationFactMapper,
221	): Promise<MutationPlan> {
222	  const view = threadView(thread) as unknown as Record<string, unknown>;
223	  const rethrow: Rethrow = (error, fact) => {
224	    if (fact && mapFact) throw mapFact(fact, opIndex, op.op);
225	    throw mapFailure ? mapFailure(error, opIndex, op.op) : error;
226	  };
227	
228	  switch (op.op) {
229	    case 'set': {
230	      authored(() => assertMutablePath(op.path), rethrow, 'target');
231	      const value = await resolveValue(op.value, view, rethrow);
232	      const exists = authored(() => getAtPointer(thread, op.path), rethrow, 'target').found;
233	      return { kind: 'patch', patch: [{ op: exists ? 'replace' : 'add', path: op.path, value }] };
234	    }
235	    case 'delete': {
236	      authored(() => assertMutablePath(op.path), rethrow, 'target');
237	      if (!authored(() => getAtPointer(thread, op.path), rethrow, 'target').found)
238	        return { kind: 'patch', patch: [] };
239	      return { kind: 'patch', patch: [{ op: 'remove', path: op.path }] };
240	    }
241	    case 'append-message': {
242	      const content = await renderValue(op.content, view, rethrow);
243	      const message = makeMessage(ctx, op.role, content, op.tags);
244	      return {
245	        kind: 'patch',
246	        patch: [{ op: 'add', path: '/messages/-', value: messageJson(message) }],
247	      };
248	    }
249	    case 'inject': {
250	      const index =
251	        op.position === 'start'
252	          ? 0
253	          : op.position === 'end'
254	            ? thread.messages.length
255	            : Math.min(op.position, thread.messages.length);
256	      const patch: PatchOperation[] = [];
257	      for (const [offset, injected] of op.messages.entries()) {
258	        const content = await renderValue(injected.content, view, rethrow, offset);
259	        patch.push({
260	          op: 'add',
261	          path: `/messages/${index + offset}`,
262	          value: messageJson(makeMessage(ctx, injected.role, content, injected.tags)),
263	        });
264	      }
265	      return { kind: 'patch', patch };
266	    }
267	    case 'truncate': {
268	      const candidates = op.where
269	        ? await selectIndices(thread.messages, op.where, view, rethrow)
270	        : thread.messages.map((_, i) => i);
271	      const keep = new Set<number>();
272	      if (op.keep.first !== undefined)
273	        candidates.slice(0, op.keep.first).forEach((i) => keep.add(i));
274	      if (op.keep.last !== undefined)
