21	  type TemplateError,
22	  type MutationContext,
23	  type MutationFactMapper,
24	  type TemplateFact,
25	  type MutationFailureMapper,
26	  type RepairRequest,
27	} from '@graphgoblin/domain';
28	import { applyMutations, completeRepair, applyPatch } from '@graphgoblin/domain';
29	import type { MutationOperation, NodeKind } from '@graphgoblin/contracts';
30	import { predicateAuthored, type AuthoredSite } from '../authored-failure.js';
31	import { RunFailureError } from '../errors.js';
32	import type { NodeContext } from '../handler.js';
