34	
35	export function toJson(value: unknown): JsonValue {
36	  if (value === undefined) return null;
37	  return JSON.parse(JSON.stringify(value)) as JsonValue;
38	}
39	
40	/** Try to parse text as JSON; return the text itself when it is not JSON. */
41	export function jsonOrText(text: string): JsonValue {
42	  const trimmed = text.trim();
43	  if (trimmed === '') return '';
44	  try {
45	    return JSON.parse(trimmed) as JsonValue;
46	  } catch {
47	    return text;
48	  }
49	}
50	
51	/** Patch operations that record a node's output in `/outputs/<nodeId>` and `/lastOutput`. */
52	export function outputPatch(
53	  thread: ContextThread,
54	  nodeId: string,
55	  value: JsonValue,
56	  at: string,
57	  schemaRef?: string,
58	): PatchOperation[] {
59	  const output: NodeOutput = { nodeId, value, at, ...(schemaRef ? { schemaRef } : {}) };
60	  const outputJson = toJson(output);
61	  return [
62	    {
63	      op: Object.prototype.hasOwnProperty.call(thread.outputs, nodeId) ? 'replace' : 'add',
64	      path: formatPointer(['outputs', nodeId]),
65	      value: outputJson,
66	    },
67	    { op: thread.lastOutput ? 'replace' : 'add', path: '/lastOutput', value: outputJson },
68	  ];
69	}
70	
71	export function messagePatch(message: Message): PatchOperation {
72	  return { op: 'add', path: '/messages/-', value: toJson(message) };
73	}
74	
75	export function makeMessage<K extends NodeKind>(
76	  ctx: NodeContext<K>,
77	  role: MessageRole,
78	  content: string,
79	  tags?: string[],
80	): Message {
81	  return {
82	    id: ctx.services.newId(),
83	    role,
84	    content,
85	    nodeId: ctx.node.id,
86	    ts: ctx.services.now(),
87	    ...(tags ? { tags } : {}),
88	  };
89	}
90	
91	export function addUsage(a: Usage, b: Partial<Usage>): Usage {
92	  return {
93	    inputTokens: a.inputTokens + (b.inputTokens ?? 0),
94	    outputTokens: a.outputTokens + (b.outputTokens ?? 0),
95	    cachedInputTokens: a.cachedInputTokens + (b.cachedInputTokens ?? 0),
96	    reasoningOutputTokens: a.reasoningOutputTokens + (b.reasoningOutputTokens ?? 0),
97	  };
98	}
99	
100	export function usagePatch(thread: ContextThread, usage: Partial<Usage>): PatchOperation[] {
101	  return [
102	    {
103	      op: 'replace',
104	      path: '/counters/usage',
105	      value: toJson(addUsage(thread.counters.usage, usage)),
106	    },
107	  ];
108	}
109	
110	export async function selectMessages(
111	  messages: readonly Message[],
112	  selection: MessageSelection | undefined,
113	  view: Record<string, unknown>,
114	  site: AuthoredSite,
115	): Promise<Message[]> {
116	  if (selection === undefined || selection === 'all') return [...messages];
117	  if (selection === 'none') return [];
118	  if (selection === 'last')
119	    return messages.length ? [messages[messages.length - 1] as Message] : [];
120	  if (typeof selection === 'number')
121	    return messages.slice(Math.max(0, messages.length - selection));
122	  const out: Message[] = [];
123	  for (const [index, message] of messages.entries()) {
124	    if (
125	      await predicateAuthored({ ...site, itemIndex: index }, selection.where, message, {
126	        bindings: { thread: view, index },
127	      })
128	    )
129	      out.push(message);
130	  }
131	  return out;
132	}
133	
134	export async function selectCollection<T>(
135	  items: readonly T[],
136	  selection: CollectionSelection | undefined,
137	  view: Record<string, unknown>,
138	  site: AuthoredSite,
139	): Promise<T[]> {
140	  if (selection === undefined || selection === 'all') return [...items];
141	  if (selection === 'none') return [];
142	  const out: T[] = [];
143	  for (const [index, item] of items.entries()) {
144	    if (
145	      await predicateAuthored({ ...site, itemIndex: index }, selection.where, item, {
146	        bindings: { thread: view, index },
147	      })
148	    )
149	      out.push(item);
150	  }
151	  return out;
152	}
153	
154	export function mutationContext<K extends NodeKind>(ctx: NodeContext<K>): MutationContext {
155	  return { nodeId: ctx.node.id, newId: () => ctx.services.newId(), now: () => ctx.services.now() };
156	}
157	
158	/** Combine the run's abort signal with an optional timeout. */
159	export function withTimeout(
160	  signal: AbortSignal,
161	  timeoutSeconds: number | undefined,
162	  onTimeout: () => Error,
163	): { signal: AbortSignal; dispose: () => void; timedOut: () => boolean } {
164	  if (timeoutSeconds === undefined)
165	    return { signal, dispose: () => undefined, timedOut: () => false };
166	  const controller = new AbortController();
167	  let timedOut = false;
168	  const timer = setTimeout(() => {
169	    timedOut = true;
170	    controller.abort(onTimeout());
171	  }, timeoutSeconds * 1000);
172	  const forward = (): void => controller.abort(signal.reason);
173	  if (signal.aborted) forward();
174	  else signal.addEventListener('abort', forward, { once: true });
175	  return {
176	    signal: controller.signal,
177	    dispose: () => {
178	      clearTimeout(timer);
179	      signal.removeEventListener('abort', forward);
180	    },
181	    timedOut: () => timedOut,
182	  };
183	}
184	
185	export const DEFAULT_REPAIR_PROMPT = [
186	  'A value was expected to match a JSON Schema but did not.',
187	  'Return only a corrected JSON value that satisfies the schema. Do not explain.',
188	  '',
189	  'Schema:',
190	  '{{ schema }}',
191	  '',
192	  'Value:',
193	  '{{ value }}',
194	  '',
195	  'Validation errors:',
196	  '{% for e in errors %}- {{ e }}',
197	  '{% endfor %}',
198	].join('\n');
199	
200	/**
201	 * Repair a value through the structured-completion port until it satisfies the schema or the
202	 * policy is exhausted. Returns the repaired value, the raw value when `continue-raw` applies,
203	 * or throws OUTPUT_SCHEMA_MISMATCH.
204	 */
205	export async function repairValue<K extends NodeKind>(
206	  ctx: NodeContext<K>,
207	  input: {
208	    value: unknown;
209	    schema: JsonSchema;
210	    errors: string[];
211	    repair: RepairPolicy;
212	    model?: string;
213	    effort?: Effort;
214	    onPromptFact?: (fact: TemplateFact) => unknown;
215	    onPromptFailure?: (error: TemplateError) => unknown;
216	  },
217	): Promise<{ value: JsonValue; repaired: boolean }> {
218	  const { repair } = input;
219	  let errors = input.errors;
220	  if (repair.enabled && repair.maxAttempts > 0) {
221	    const structured = ctx.ports.structured;
222	    if (!structured) {
223	      throw new RunFailureError(
224	        'DECIDER_UNAVAILABLE',
225	        'schema repair needs a structured completion provider and none is configured',
226	        { nodeId: ctx.node.id },
227	      );
228	    }
229	    const { model, effort } = await ctx.services.resolveModel('codex', input.model, input.effort);
230	    for (let attempt = 1; attempt <= repair.maxAttempts; attempt += 1) {
231	      const view = {
232	        ...threadView(ctx.thread),
233	        schema: JSON.stringify(input.schema, null, 2),
234	        value: JSON.stringify(input.value ?? null, null, 2),
235	        errors,
236	        attempt,
237	      };
238	      const rendered = await observeTemplate(repair.prompt ?? DEFAULT_REPAIR_PROMPT, view);
239	      if (!rendered.ok) {
240	        if (input.onPromptFact) throw input.onPromptFact(rendered.fact);
241	        throw input.onPromptFailure ? input.onPromptFailure(rendered.error) : rendered.error;
242	      }
243	      const prompt = rendered.value;
244	      const completion = await completeWithDeadline(
245	        (signal) => structured.complete({ prompt, schema: input.schema, model, effort }, signal),
246	        ctx.signal,
247	        ctx.run.pinned.limits.structuredTimeoutMs,
248	        ctx.ports.logger,
249	        { runId: ctx.run.id, nodeId: ctx.node.id },
250	      ).catch((error: unknown) => {
251	        if (error instanceof RunFailureError && error.code === 'STRUCTURED_COMPLETION_TIMEOUT')
252	          throw new RunFailureError(error.code, error.message, {
253	            ...error.options,
254	            details: {
255	              timeoutMs: ctx.run.pinned.limits.structuredTimeoutMs,
256	              provenance: { kind: 'llm', provider: 'codex', classifierId: null, model, effort },
257	            },
258	          });
259	        throw error;
260	      });
261	      const validation = validateJson(input.schema, completion.value);
262	      if (validation.ok) return { value: toJson(completion.value), repaired: true };
263	      errors = validation.errors;
264	    }
265	  }
266	  if (repair.onFailure === 'continue-raw') return { value: toJson(input.value), repaired: false };
267	  throw new RunFailureError(
268	    'OUTPUT_SCHEMA_MISMATCH',
269	    `value does not match the required schema: ${errors.join('; ')}`,
270	    {
271	      nodeId: ctx.node.id,
272	      details: { errors, value: toJson(input.value) },
273	    },
274	  );
275	}
276	
277	/** Run a mutation list, repairing coerce failures through the structured port as the policy allows. */
278	export async function runMutations<K extends NodeKind>(
279	  ctx: NodeContext<K>,
280	  thread: ContextThread,
281	  ops: readonly MutationOperation[],
282	  mapFailure?: MutationFailureMapper,
283	  mapFact?: MutationFactMapper,
284	): Promise<{ thread: ContextThread; patch: PatchOperation[] }> {
285	  const mctx = mutationContext(ctx);
286	  let current = thread;
287	  const patch: PatchOperation[] = [];
288	  let startAt = 0;
289	  for (;;) {
290	    const result = await applyMutations(current, ops, mctx, startAt, mapFailure, mapFact);
291	    current = result.thread;
292	    patch.push(...result.patch);
293	    if (!result.pending) return { thread: current, patch };
294	    const pending: RepairRequest = result.pending;
295	    const repaired = await repairValue(ctx, {
296	      value: pending.value,
297	      schema: pending.jsonSchema,
298	      errors: pending.errors,
299	      repair: pending.repair,
300	      ...(mapFact
301	        ? {
302	            onPromptFact: (fact: TemplateFact) =>
303	              mapFact({ kind: 'template', fact }, pending.opIndex, 'coerce'),
304	          }
305	        : {}),
306	      ...(mapFailure
307	        ? { onPromptFailure: (error) => mapFailure(error, pending.opIndex, 'coerce') }
308	        : {}),
309	    });
310	    try {
311	      if (repaired.repaired) {
312	        const done = completeRepair(current, pending, repaired.value);
313	        current = done.thread;
314	        patch.push(...done.patch);
315	      } else {
316	        const op: PatchOperation = {
317	          op: hasPath(current, pending.target) ? 'replace' : 'add',
318	          path: pending.target,
319	          value: repaired.value,
320	        };
