76	const ZERO_USAGE: Usage = {
77	  inputTokens: 0,
78	  outputTokens: 0,
79	  cachedInputTokens: 0,
80	  reasoningOutputTokens: 0,
81	};
82	
83	const CONTINUATION_PROMPT =
84	  'The previous turn was interrupted before GraphGoblin recorded its result. Continue the task from where you left off and finish it.';
85	
86	function progressSummary(item: HarnessItem): string {
87	  if (item.type === 'error') return 'Harness reported an error';
88	  if (item.type === 'tool-call') {
89	    const diagnostic = item.summary.indexOf(' failed: ');
90	    if (diagnostic >= 0)
91	      return `${item.summary.slice(0, diagnostic)} failed`.slice(0, PROGRESS_SUMMARY_MAX);
92	  }
93	  return item.summary.slice(0, PROGRESS_SUMMARY_MAX);
94	}
95	
96	function safeStatus(status: HarnessItem['status']): ProgressItemStatus | undefined {
97	  return status === 'ok' || status === 'failed' || status === 'running' ? status : undefined;
98	}
99	
100	function progressFor(item: HarnessItem): NodeProgress {
101	  const reportedStatus = safeStatus(item.status);
102	  if (item.type !== 'command') {
103	    return {
104	      item: {
105	        id: item.id,
106	        type: item.type,
107	        summary: progressSummary(item),
108	        ...(reportedStatus ? { status: reportedStatus } : {}),
109	      },
110	    };
111	  }
112	
113	  const candidateExitCode = item.exitCode;
114	  const exitCode =
115	    typeof candidateExitCode === 'number' && Number.isInteger(candidateExitCode)
116	      ? candidateExitCode
117	      : undefined;
118	  const status: ProgressItemStatus =
119	    reportedStatus === 'failed' || (exitCode !== undefined && exitCode !== 0)
120	      ? 'failed'
121	      : reportedStatus === 'ok' || exitCode === 0
122	        ? 'ok'
123	        : 'running';
124	  return {
125	    item: {
126	      id: item.id,
127	      type: item.type,
128	      summary: progressSummary(item),
129	      commandPreview: (item.commandPreview ?? item.summary)
130	        .replace(/\s+/g, ' ')
131	        .trim()
132	        .slice(0, COMMAND_PREVIEW_MAX),
133	      ...(exitCode !== undefined ? { exitCode } : {}),
134	      status,
135	    },
136	  };
137	}
138	
139	interface TurnFailures {
140	  evidence?: HarnessFailureEvidence | undefined;
141	  rejected: boolean;
142	  acceptanceFailure?: { error: unknown };
143	  recording: { operation: InferenceRecordingOperation }[];
144	}
145	
146	function recordingFault(
147	  ctx: NodeContext<'inference'>,
148	  pending: PendingTurn,
149	  state: TurnFailures,
150	  operation: InferenceRecordingOperation,
151	  error: unknown,
152	): void {
153	  state.recording.push({ operation });
154	  ctx.ports.logger.error(
155	    {
156	      runId: ctx.run.id,
157	      nodeId: ctx.node.id,
158	      turnId: pending.turn.turnId,
159	      operation,
160	      error: errorDiagnostic(error),
161	    },
162	    'inference recording failed',
163	  );
164	}
165	function observe(state: TurnFailures, error: unknown): void {
166	  state.evidence = mergeHarnessFailure(state.evidence, harnessFailureEvidence(error));
167	}
168	
169	function requireAcceptanceRecording(state: TurnFailures): void {
170	  if (state.acceptanceFailure) throw state.acceptanceFailure.error;
171	}
172	
173	/** Recording is secondary: it cannot replace the selected evidence or authorize another call. */
174	async function recordSubmission(
175	  ctx: NodeContext<'inference'>,
176	  pending: PendingTurn,
177	  state: TurnFailures,
178	  value: Parameters<typeof submission>[2],
179	  marker?: Parameters<typeof submission>[3],
180	): Promise<void> {
181	  try {
182	    await submission(ctx, pending, value, marker);
183	  } catch (error) {
184	    recordingFault(ctx, pending, state, 'harness.submission', error);
185	    if (marker) state.acceptanceFailure = { error };
186	  }
187	}
188	
189	async function recordSession(
190	  ctx: NodeContext<'inference'>,
191	  row: HarnessSessionRecord,
192	  event: Extract<HarnessEvent, { type: 'session' }>,
193	): Promise<void> {
194	  await ctx.services.record({
195	    type: 'harness.session',
196	    nodeId: ctx.node.id,
197	    harness: ctx.config.harness,
198	    sessionId: event.sessionId,
199	    mode: event.mode,
200	    ...(row.model ? { model: row.model } : {}),
201	    ...(row.effort ? { effort: row.effort } : {}),
202	  });
203	}
204	/** Fold every provider boundary into the same invocation's evidence, independently of writes. */
205	async function consume(
206	  ctx: NodeContext<'inference'>,
207	  session: HarnessSession,
208	  row: HarnessSessionRecord,
209	  pending: PendingTurn,
210	  state: TurnFailures,
211	): Promise<HarnessResult> {
212	  let resumed: Extract<HarnessEvent, { type: 'session' }> | undefined;
213	  async function* events() {
214	    try {
215	      yield* session.events;
216	    } catch (error) {
217	      if (!(error instanceof RunFailureError) || isHarnessFailureCode(error.code)) {
218	        observe(state, error);
219	        state.rejected = true;
220	      }
221	      throw error;
222	    }
223	  }
224	  for await (const event of events()) {
225	    switch (event.type) {
226	      case 'session':
227	        row.sessionId = event.sessionId;
228	        pending.sessionId = event.sessionId;
229	        row.status = 'active';
230	        row.updatedAt = ctx.services.now();
231	        await ctx.ports.sessions.upsert({ ...row });
232	        if (event.mode === 'resumed') resumed = event;
233	        else await recordSession(ctx, row, event);
234	        break;
235	      case 'submitted':
236	        await recordSubmission(ctx, pending, state, 'submitted', event.marker);
237	        break;
238	      case 'item':
239	        await ctx.services.record({
240	          type: 'node.progress',
241	          nodeId: ctx.node.id,
242	          progress: progressFor(event.item),
243	        });
244	        break;
245	      case 'usage':
246	        await ctx.services.record({
247	          type: 'harness.usage',
248	          nodeId: ctx.node.id,
249	          usage: event.usage,
250	        });
251	        break;
252	      case 'error':
253	        observe(state, event);
254	        await recordSubmission(
255	          ctx,
256	          pending,
257	          state,
258	          harnessFailureSubmission(state.evidence!, pending.submission, pending.accepted),
259	        );
260	        break;
261	      case 'turn-complete':
262	        break;
263	    }
264	  }
265	  let result: HarnessResult;
266	  try {
267	    result = await session.result;
268	  } catch (error) {
269	    if (!(error instanceof RunFailureError) || isHarnessFailureCode(error.code)) {
270	      observe(state, error);
271	      state.rejected = true;
272	    }
273	    throw error;
274	  }
275	  // Keep the requested handle as provenance immediately, but claim reuse only on success.
276	  if (resumed) await recordSession(ctx, row, resumed);
277	  return result;
278	}
