332	          nodeId: ctx.node.id,
333	          resumable: false,
334	          missingSession,
335	          ...(task ? { inference: provenance(task) } : {}),
336	        },
337	      );
338	    };
339	    if (pending?.submission === 'session-missing') throw missingFailure(pending);
340	    const workingDirectory = nodeWorkingDirectory(
341	      await ctx.services.workingDirectory(),
342	      ctx.node.id,
343	    );
344	
345	    // Input transforms shape only the view the prompt sees; they are not persisted.
346	    const viewThread: ContextThread = config.input.length
347	      ? (
348	          await runMutations(ctx, ctx.thread, config.input, undefined, (fact, index, kind) =>
349	            transformFailure(ctx.node.id, 'inference.input', fact, index, kind),
350	          )
351	        ).thread
352	      : ctx.thread;
353	    const view = threadView(viewThread) as unknown as Record<string, unknown>;
354	
355	    for (const [fileIndex, file] of (config.contextFiles ?? []).entries()) {
356	      await ctx.ports.workspace.writeFile(
357	        workingDirectory,
358	        file.path,
359	        await renderAuthored(
360	          { nodeId: ctx.node.id, boundary: 'inference.contextFiles.template', fileIndex },
361	          file.template,
362	          view,
363	        ),
364	      );
365	    }
366	
367	    let resumeId: string | undefined;
368	    let prompt: string;
369	    let promptKind: PendingTurn['turn']['promptKind'] = 'authored';
370	    if (pending) {
371	      if (pending.submission === 'definitely-not-submitted') {
372	        prompt = pending.turn.prompt;
373	        promptKind = pending.turn.promptKind;
374	        resumeId = pending.turn.resumeSessionId;
375	      } else {
376	        resumeId = pending.sessionId;
377	        prompt = CONTINUATION_PROMPT;
378	        promptKind = 'continuation';
379	      }
380	    } else {
381	      prompt =
382	        visit.freshSession?.prompt ??
383	        (await renderAuthored(
384	          { nodeId: ctx.node.id, boundary: 'inference.prompt.template' },
385	          config.prompt.template,
386	          view,
387	        ));
388	      if (visit.freshSession) {
389	        // This explicit choice applies only to this logical visit; the authored policy stays.
390	        resumeId = undefined;
391	      } else if (config.session.policy === 'resume-previous') {
392	        resumeId = (await ctx.ports.sessions.latestWithSession(ctx.run.id, config.harness))
393	          ?.sessionId;
394	      } else if (config.session.policy === 'resume-named') {
395	        resumeId = (
396	          await ctx.ports.sessions.byScopeKey(
397	            `${ctx.thread.run.loopId}:${config.session.key}`,
398	            config.harness,
399	          )
400	        )?.sessionId;
401	      } else if (config.session.policy === 'resume-own' && visit.completedVisits > 0) {
402	        const reset = config.session.resetAfterVisits;
403	        // Pending turns above retain #244's exact retry/continuation and inherited-ID rules,
404	        // including at a reset boundary. Forks/children have separate run IDs and logs.
405	        if (reset === undefined || visit.completedVisits % reset !== 0) {
406	          const previous =
407	            visit.completedAttempt === undefined
408	              ? undefined
409	              : await ctx.ports.sessions.forNodeAttempt(
410	                  ctx.run.id,
411	                  ctx.node.id,
412	                  visit.completedAttempt,
413	                  config.harness,
414	                );
415	          if (!previous?.sessionId) throw missingFailure();
416	          resumeId = previous.sessionId;
417	        }
418	      }
419	    }
420	    const timeout = withTimeout(ctx.signal, config.timeoutSeconds, () =>
421	      Object.assign(new Error('inference timeout'), { code: 'HARNESS_TIMEOUT' }),
422	    );
423	    let admittedContext: Awaited<ReturnType<typeof admitInferencePrompt>>['context'] | undefined;
424	    if (harness?.contextWindow) {
425	      try {
426	        const window = await harness.contextWindow(
427	          {
428	            workingDirectory,
429	            model,
430	            effort,
431	            options: config.harnessOptions,
432	            ...(config.capabilities ? { capabilities: config.capabilities } : {}),
433	            turn: {
434	              prompt,
435	              ...(config.output.schema?.native
436	                ? { outputSchema: config.output.schema.jsonSchema }
437	                : {}),
438	            },
439	          },
440	          timeout.signal,
441	        );
442	        const admitted = await admitInferencePrompt({
443	          prompt,
444	          template: config.prompt.template,
445	          thread: viewThread,
446	          allowHistoryTrim:
447	            !visit.pending &&
448	            !visit.freshSession &&
449	            ctx.node.id === 'respond' &&
450	            systemChatIssues(ctx.definition).length === 0,
451	          window,
452	        });
453	        prompt = admitted.prompt;
454	        admittedContext = admitted.context;
455	      } catch (error) {
456	        timeout.dispose();
457	        if (timeout.timedOut())
458	          throw new RunFailureError(
459	            'INFERENCE_TIMEOUT',
460	            `Inference exceeded ${config.timeoutSeconds ?? 0}s before context admission; no provider inference was submitted.`,
461	            { nodeId: ctx.node.id, resumable: true },
462	          );
463	        if (ctx.signal.aborted || isAbortError(error)) throw new RunCancelledError();
464	        if (error instanceof RunFailureError) throw error;
465	        throw mapHarnessFailure(error, undefined, ctx.node.id, config.harness).failure;
466	      }
467	    }
468	    const beginTurn = (
469	      text: string,
470	      kind: PendingTurn['turn']['promptKind'],
471	      id?: string,
472	    ): PendingTurn => {
473	      const turn = {
474	        visitId: visit.visitId,
475	        turnId: ctx.services.newId(),
476	        harness: config.harness,
477	        prompt: text,
478	        promptKind: kind,
479	        ...(admittedContext
480	          ? {
481	              context:
482	                kind === 'authored'
483	                  ? admittedContext
484	                  : { ...admittedContext, retainedHistoryPairs: 0, omittedHistoryPairs: 0 },
485	            }
486	          : {}),
487	        ...(id ? { resumeSessionId: id } : {}),
488	      };
489	      return {
490	        turn,
491	        submission: 'delivery-uncertain',
492	        accepted: false,
493	        ...(id ? { sessionId: id } : {}),
494	      };
495	    };
496	    const recordTurn = (task: PendingTurn) =>
497	      ctx.services.record({ type: 'harness.turn', nodeId: ctx.node.id, ...task.turn });
498	    // A safe retry retains the original turn identity and exact rendered prompt.
499	    if (!pending || pending.submission !== 'definitely-not-submitted') {
500	      pending = beginTurn(prompt, promptKind, resumeId);
501	      // A crash after this append may occur on either side of invocation: uncertain by default.
502	    } else {
503	      // Re-record the same task intent before another invocation. This resets any init-only ID
504	      // from the refused invocation, so a fresh retry cannot recover into that unused session.
505	      pending = {
506	        turn: pending.turn,
507	        submission: 'delivery-uncertain',
508	        accepted: false,
509	        ...(resumeId ? { sessionId: resumeId } : {}),
510	      };
511	    }
512	
513	    const row: HarnessSessionRecord = {
514	      runId: ctx.run.id,
515	      nodeId: ctx.node.id,
516	      attempt: ctx.attempt,
517	      harness: config.harness,
518	      status: 'starting',
519	      model,
520	      effort,
521	      updatedAt: ctx.services.now(),
522	      ...(resumeId ? { sessionId: resumeId } : {}),
523	      ...(config.session.policy === 'resume-named'
524	        ? { scopeKey: `${ctx.thread.run.loopId}:${config.session.key}` }
525	        : {}),
526	    };
527	    const schema = config.output.schema;
528	    const turn: HarnessTurnRequest = {
529	      prompt,
530	      ...(schema?.native ? { outputSchema: schema.jsonSchema } : {}),
531	    };
532	    const sessionRequest = (next: HarnessTurnRequest): HarnessStartRequest => ({
533	      workingDirectory,
534	      model,
535	      effort,
536	      options: config.harnessOptions,
537	      ...(config.capabilities ? { capabilities: config.capabilities } : {}),
538	      turn: next,
539	    });
540	
541	    let afterResultFailure: RunFailureError | undefined;
542	    let result: HarnessResult;
543	    let session: HarnessSession | undefined;
544	    let invoking = false;
545	    let intentUnconfirmed = true;
546	    pending.intentUnconfirmed = true;
547	    const failures: TurnFailures = { rejected: false, recording: [] };
548	    let usage: Usage = ZERO_USAGE;
549	    try {
550	      // Initial tasks, exact retries and repairs share the same guarded intent boundary.
551	      await recordTurn(pending);
552	      intentUnconfirmed = false;
553	      pending.intentUnconfirmed = false;
554	      await ctx.ports.sessions.upsert({ ...row });
555	      if (!harness) {
556	        throw new RunFailureError(
557	          'HARNESS_NOT_INSTALLED',
558	          `harness "${config.harness}" is not configured`,
559	          { nodeId: ctx.node.id },
560	        );
561	      }
562	      invoking = true;
563	      // F3's one retry uses F4's selected evidence, including acceptance and recording faults.
564	      for (let retry = 0; ; retry += 1) {
565	        session = resumeId
566	          ? harness.resume(resumeId, sessionRequest(turn), timeout.signal)
567	          : harness.start(sessionRequest(turn), timeout.signal);
568	        try {
569	          result = await consume(ctx, session, row, pending, failures);
570	          requireAcceptanceRecording(failures);
571	          failures.evidence = undefined;
572	          break;
573	        } catch (error) {
574	          const selected = mapHarnessFailure(error, failures.evidence, ctx.node.id, config.harness);
575	          const state = harnessFailureSubmission(
576	            selected.evidence,
577	            pending.submission,
578	            pending.accepted || pending.acceptanceObserved,
579	          );
580	          if (
581	            retry >= 1 ||
582	            selected.failure.code !== 'HARNESS_TRANSPORT_FAILED' ||
583	            !selected.evidence.retriable ||
584	            state !== 'definitely-not-submitted' ||
585	            failures.acceptanceFailure ||
586	            failures.recording.length ||
587	            timeout.signal.aborted
588	          )
589	            throw error;
590	          failures.evidence = selected.evidence;
591	          try {
592	            await session.cancel();
593	          } catch (cleanupError) {
594	            observe(failures, cleanupError);
595	            failures.rejected = true;
596	            throw error;
597	          }
598	          await recordSubmission(ctx, pending, failures, state);
599	          if (failures.recording.length) throw error;
600	          // Establish the exact retry intent before its fallible append. Recovery must not
601	          // confuse the retired handle with a new invocation that has not happened yet.
602	          session = undefined;
603	          invoking = false;
604	          pending = {
605	            turn: pending.turn,
606	            submission: 'delivery-uncertain',
607	            accepted: false,
608	            ...(resumeId ? { sessionId: resumeId } : {}),
609	            intentUnconfirmed: true,
610	          };
611	          intentUnconfirmed = true;
612	          failures.evidence = undefined;
613	          failures.rejected = false;
614	          await recordTurn(pending);
615	          intentUnconfirmed = false;
616	          pending.intentUnconfirmed = false;
617	          invoking = true;
618	        }
619	      }
620	      usage = addUsage(usage, result.usage);
621	
622	      // Structured output: validate, then repair on the same session as the policy allows.
623	      let output: JsonValue;
624	      if (schema) {
625	        let candidate: unknown = outputCandidate(result);
626	        let validation = validateJson(schema.jsonSchema, candidate);
627	        let attempts = 0;
628	        while (!validation.ok && schema.repair.enabled && attempts < schema.repair.maxAttempts) {
629	          attempts += 1;
630	          const sessionId = row.sessionId;
631	          if (!sessionId) break;
632	          const rendered = await observeTemplate(schema.repair.prompt ?? DEFAULT_REPAIR_PROMPT, {
633	            ...view,
634	            schema: JSON.stringify(schema.jsonSchema, null, 2),
635	            value: JSON.stringify(candidate ?? null, null, 2),
636	            errors: validation.errors,
637	            attempt: attempts,
638	          });
639	          if (!rendered.ok) {
640	            afterResultFailure = authoredFailure(
641	              {
642	                nodeId: ctx.node.id,
643	                boundary: 'inference.output.schema.repair.prompt',
644	                attempt: attempts,
645	              },
646	              { kind: 'template', fact: rendered.fact },
647	            );
648	            throw afterResultFailure;
649	          }
650	          const repairPrompt = rendered.value;
651	          // Establish the repair task and release the completed handle before persistence:
652	          // an append can commit and then throw, without any repair invocation having started.
653	          session = undefined;
654	          invoking = false;
655	          pending = beginTurn(repairPrompt, 'repair', sessionId);
656	          intentUnconfirmed = true;
657	          pending.intentUnconfirmed = true;
658	          await recordTurn(pending);
659	          intentUnconfirmed = false;
660	          pending.intentUnconfirmed = false;
661	          failures.evidence = undefined;
662	          failures.rejected = false;
663	          invoking = true;
664	          session = harness.resume(
665	            sessionId,
666	            sessionRequest({ prompt: repairPrompt, outputSchema: schema.jsonSchema }),
667	            timeout.signal,
668	          );
669	          const repairResult = await consume(ctx, session, row, pending, failures);
670	          requireAcceptanceRecording(failures);
671	          failures.evidence = undefined;
672	          usage = addUsage(usage, repairResult.usage);
673	          result = {
674	            ...result,
675	            items: [...result.items, ...repairResult.items],
676	            finalText: repairResult.finalText,
677	          };
678	          candidate = outputCandidate(repairResult);
679	          validation = validateJson(schema.jsonSchema, candidate);
680	        }
681	        if (validation.ok) {
682	          output = toJson(candidate);
683	        } else if (schema.repair.onFailure === 'continue-raw') {
684	          output = toJson(candidate);
685	        } else {
686	          throw new RunFailureError(
687	            'OUTPUT_SCHEMA_MISMATCH',
688	            `harness output does not match the required schema: ${validation.errors.join('; ')}`,
689	            {
690	              nodeId: ctx.node.id,
691	              details: { errors: validation.errors, value: toJson(candidate) },
692	            },
693	          );
694	        }
695	      } else {
696	        output = config.output.capture === 'text' ? result.finalText : jsonOrText(result.finalText);
697	      }
698	
699	      // Build the patch: transcript artifact, messages, output, usage.
700	      const patch: PatchOperation[] = [];
701	      let working = ctx.thread;
702	      if (config.output.captureTranscript === 'artifact') {
703	        const stored = await ctx.ports.artifacts.put(
704	          'transcript',
705	          JSON.stringify(result.items),
706	          ctx.run.id,
707	        );
708	        patch.push({
709	          op: 'add',
710	          path: '/artifacts/-',
711	          value: toJson({
712	            id: ctx.services.newId(),
713	            kind: 'transcript',
714	            ref: stored.ref,
715	            nodeId: ctx.node.id,
716	            bytes: stored.bytes,
717	            label: `transcript ${ctx.node.id}`,
718	          }),
719	        });
720	      }
721	      if (config.output.toMessages !== 'none') {
722	        if (config.output.toMessages === 'final-and-notes') {
723	          for (const item of result.items) {
724	            const note = noteFor(item);
725	            if (note) patch.push(messagePatch(makeMessage(ctx, 'note', note, ['harness-note'])));
726	          }
727	        }
728	        patch.push(messagePatch(makeMessage(ctx, 'assistant', result.finalText)));
729	      }
730	      patch.push(...outputPatch(working, ctx.node.id, output, ctx.services.now()));
731	      patch.push(...usagePatch(working, usage));
732	      working = applyPatch(working, patch);
733	
734	      if (config.output.transforms.length) {
735	        const transformed = await runMutations(
736	          ctx,
737	          working,
738	          config.output.transforms,
739	          undefined,
740	          (fact, index, kind) => {
741	            afterResultFailure = transformFailure(
742	              ctx.node.id,
743	              'inference.output.transforms',
744	              fact,
745	              index,
746	              kind,
747	            );
748	            return afterResultFailure;
749	          },
750	        );
751	        patch.push(...transformed.patch);
752	      }
753	
754	      row.status = 'finished';
755	      row.updatedAt = ctx.services.now();
756	      await ctx.ports.sessions.upsert({ ...row });
757	      return { kind: 'done', patch, route: 'out' };
758	    } catch (error) {
759	      let failure: unknown = error;
760	      if (!session && invoking && !(error instanceof RunCancelledError)) {
761	        observe(failures, error);
762	        failures.rejected = true;
763	      }
764	      if (intentUnconfirmed) {
765	        // Establishing the current intent preceded this fallible append. Reconcile only against
766	        // the real log; a failed read must retain the intent, never restore the completed handle.
767	        try {
768	          const turnId = pending.turn.turnId;
769	          const history = await ctx.ports.events.read(ctx.run.id);
770	          if (!history.some((event) => event.type === 'harness.turn' && event.turnId === turnId))
771	            await recordTurn(pending);
772	          pending.intentUnconfirmed = false;
773	        } catch (recordError) {
774	          recordingFault(ctx, pending, failures, 'turn.intent.reconcile', recordError);
775	        }
776	      }
777	      const unconfirmed = () =>
778	        failures.evidence?.code.toUpperCase() === 'HARNESS_TERMINATION_UNCONFIRMED';
779	      if (session && !unconfirmed()) {
780	        try {
781	          await session.cancel();
782	        } catch (cleanupError) {
783	          observe(failures, cleanupError);
784	          // Cleanup participates in the same fold. Safety evidence can supersede an engine
785	          // failure too; an ordinary cleanup diagnostic cannot replace a non-provider cause.
786	          if (harnessFailureRank(failures.evidence!) >= 4) failures.rejected = true;
787	          else
788	            ctx.ports.logger.warn(
789	              {
790	                nodeId: ctx.node.id,
791	                code: mapHarnessFailure(cleanupError, undefined, ctx.node.id, config.harness)
792	                  .failure.code,
793	              },
794	              'harness cleanup failed',
795	            );
796	        }
797	      }
798	      if (timeout.timedOut()) {
799	        observe(failures, {
800	          code: 'HARNESS_TIMEOUT',
801	          message: 'inference exceeded ' + (config.timeoutSeconds ?? 0) + 's',
802	          retriable: true,
803	        });
804	        failures.rejected = true;
805	      }
806	      if (failures.evidence && (failures.rejected || harnessFailureRank(failures.evidence) >= 4))
807	        failure = mapHarnessFailure(
808	          failures.evidence,
809	          undefined,
810	          ctx.node.id,
811	          config.harness,
812	        ).failure;
813	      if (
814	        !unconfirmed() &&
815	        !timeout.timedOut() &&
816	        (error instanceof RunCancelledError || isAbortError(error) || ctx.signal.aborted)
817	      )
818	        failure = new RunCancelledError();
819	      if (failure instanceof ArtifactStoreError && failure.code === 'ARTIFACT_WRITE_FAILED')
820	        failure = new RunFailureError(failure.code, failure.message, {
821	          nodeId: ctx.node.id,
822	          details: { ref: failure.ref },
823	        });
824	      if (
825	        !(failure instanceof RunCancelledError) &&
826	        (!(failure instanceof RunFailureError) ||
827	          (failure.code === 'INTERNAL_ERROR' && !(failure instanceof InternalRunFailureError)))
828	      ) {
829	        const { details, ...options } = failure instanceof RunFailureError ? failure.options : {};
830	        ctx.ports.logger.error(
831	          {
832	            runId: ctx.run.id,
833	            nodeId: ctx.node.id,
834	            turnId: pending.turn.turnId,
835	            error: errorDiagnostic(failure),
836	            details,
837	          },
838	          'inference execution failed',
839	        );
840	        failure = new InternalRunFailureError(INTERNAL_FAILURE_MESSAGE, {
841	          ...options,
842	          nodeId: options.nodeId ?? ctx.node.id,
843	        });
844	      }
845	
846	      // Decide first, persist second. Even a before/after-commit storage exception can only add
847	      // details.recording; it cannot change cause, submission, cancellation precedence or retry.
848	      const state =
849	        failures.rejected && failures.evidence
850	          ? harnessFailureSubmission(
851	              failures.evidence,
852	              session ? pending.submission : 'definitely-not-submitted',
853	              pending.accepted || pending.acceptanceObserved,
854	            )
855	          : session
856	            ? pending.submission
857	            : 'definitely-not-submitted';
858	      await recordSubmission(ctx, pending, failures, state);
859	      if (!(failure instanceof RunCancelledError)) {
860	        row.status = 'failed';
861	        row.updatedAt = ctx.services.now();
862	        try {
863	          await ctx.ports.sessions.upsert({ ...row });
864	        } catch (recordError) {
865	          recordingFault(ctx, pending, failures, 'harness.status', recordError);
866	        }
867	      }
868	      if (failure instanceof RunFailureError) {
869	        const uncertain = pending.submission === 'delivery-uncertain';
870	        const missing = pending.submission === 'session-missing';
871	        // Only a generic turn failure becomes delivery uncertainty. A pinned argument,
872	        // configuration or policy refusal is a specific cause and keeps its own non-resumable
873	        // code after acceptance too, for example a request the provider refused (#243, #244).
874	        const code = missing
875	          ? 'HARNESS_SESSION_MISSING'
876	          : uncertain &&
877	              failure.code === 'HARNESS_TURN_FAILED' &&
878	              !isPinnedRefusal(failures.evidence)
879	            ? 'HARNESS_DELIVERY_UNCERTAIN'
880	            : failure.code;
881	        const details = failure.options.details;
882	        const message = missing
883	          ? missingFailure(pending).message
884	          : failure !== afterResultFailure && uncertain && !canContinueTurn(pending)
885	            ? failure.message +
886	              (failure instanceof InternalRunFailureError ? ' ' : '. ') +
887	              recoveryFailure(pending, ctx.node.id).message
888	            : failure.message;
889	        const options: RunFailureError['options'] = {
890	          ...failure.options,
891	          inference: provenance(pending),
892	          ...(missing ? { missingSession: missingFailure(pending).options.missingSession } : {}),
893	          ...(code === 'HARNESS_TERMINATION_UNCONFIRMED'
894	            ? {
895	                details: {
896	                  ...(typeof details === 'object' && details !== null && !Array.isArray(details)
897	                    ? details
898	                    : { cause: details ?? null }),
899	                  interruptedByStop:
900	                    timeout.signal.reason instanceof RunFailureError &&
901	                    timeout.signal.reason.code === 'RUN_INTERRUPTED_BY_STOP',
902	                },
903	              }
904	            : {}),
905	          ...(failures.recording.length
906	            ? {
907	                details: {
908	                  ...(typeof details === 'object' && details !== null && !Array.isArray(details)
909	                    ? details
910	                    : { cause: details ?? null }),
911	                  ...(code === 'HARNESS_TERMINATION_UNCONFIRMED'
912	                    ? {
913	                        interruptedByStop:
914	                          timeout.signal.reason instanceof RunFailureError &&
915	                          timeout.signal.reason.code === 'RUN_INTERRUPTED_BY_STOP',
916	                      }
917	                    : {}),
918	                  recording: failures.recording,
919	                },
920	              }
921	            : {}),
922	          resumable:
923	            !missing &&
924	            (!uncertain || canContinueTurn(pending)) &&
925	            failure.options.resumable !== false,
926	        };
927	        failure =
928	          code === 'INTERNAL_ERROR' && failure instanceof InternalRunFailureError
929	            ? new InternalRunFailureError(message, options)
930	            : new RunFailureError(code, message, options);
931	      }
932	      throw failure;
933	    } finally {
934	      timeout.dispose();
935	    }
936	  },
937	};
