  // finds the request as the log's last event and completes the cancellation at recovery.
  const run = await this.mustGet(runId);
  if (!run.cancelRequestedAt)
    await this.ports.events.append(runId, [
      ...records,
      { type: 'run.cancel_requested', actor: { kind: 'run', id: childRunId } },
    ]);
  await this.ports.runs.claimCancel(runId, ACTIVE_STATUSES, this.now());
  await this.finalizeCancel(runId);
}

private async depthOf(run: RunRecord): Promise<number> {
  let depth = 0;
  let current: RunRecord | undefined = run;
  while (current?.parentRunId) {
    depth += 1;
    current = await this.ports.runs.get(current.parentRunId);
    if (depth > 1000) break;
  }
  return depth;
}

private async workingDirectory(
  run: RunRecord,
  def: LoopDefinition,
  thread: ContextThread,
): Promise<WorkingDirectoryResult> {
  const cached = this.directories.get(run.id);
  if (cached !== undefined) return { ok: true, directory: cached };
  let spec = def.settings.workingDirectory;
  if (spec.kind === 'template') {
    const rendered = await observeTemplate(spec.template, { ...threadView(thread) });
    if (!rendered.ok) return { ok: false, reason: rendered.fact };
    const path = rendered.value.trim();
    if (!path) return { ok: false, reason: 'empty-path' };
    spec = { kind: 'fixed', path };
  }
  const directory = await this.ports.workspace.resolve(spec, run.id);
  this.directories.set(run.id, directory);
  return { ok: true, directory };
}

/** Execution and public reads share the same verified-checkpoint reconstruction. */
private async loadThread(run: RunRecord, events: readonly RunEvent[]): Promise<ContextThread> {
  const checkpoint = await this.ports.runs.getThreadCheckpoint(run.id, events.at(-1)?.seq ?? 0);
  const initial = await this.ports.runs.getInitialThread(run.id);
  if (!initial) throw new Error(`run ${run.id} has no initial thread`);
  return reconcileThread(initial, events, checkpoint);
}

