35	async function buildSeed(ctx: NodeContext<'subloop'>): Promise<Seed> {
36	  const { input } = ctx.config;
37	  const thread = ctx.thread;
38	  const view = threadView(thread) as unknown as Record<string, unknown>;
39	  const seed: Seed = {};
40	
41	  if (input.mode === 'inherit') {
42	    const excluded = new Set(input.exclude ?? []);
43	    if (!excluded.has('messages')) seed.messages = [...thread.messages];
44	    if (!excluded.has('vars')) seed.vars = { ...thread.vars };
45	    if (!excluded.has('artifacts')) seed.artifacts = [...thread.artifacts];
46	    if (!excluded.has('outputs')) seed.outputs = { ...thread.outputs };
47	    if (!excluded.has('lastOutput') && thread.lastOutput) seed.lastOutput = thread.lastOutput;
48	  } else if (input.mode === 'project') {
49	    seed.messages = await selectMessages(thread.messages, input.messages ?? 'none', view, {
50	      nodeId: ctx.node.id,
51	      boundary: 'subloop.input.messages.where',
52	    });
53	    seed.artifacts = await selectCollection(thread.artifacts, input.artifacts ?? 'none', view, {
54	      nodeId: ctx.node.id,
55	      boundary: 'subloop.input.artifacts.where',
56	    });
57	  }
58	
59	  if (input.vars) {
60	    const vars: Record<string, JsonValue> = { ...(seed.vars ?? {}) };
61	    for (const [mapIndex, [name, expression]] of Object.entries(input.vars).entries()) {
62	      vars[name] = toJson(
63	        await evaluateAuthored(
64	          { nodeId: ctx.node.id, boundary: 'subloop.input.vars', mapIndex },
65	          expression,
66	          view,
67	        ),
68	      );
69	    }
70	    seed.vars = vars;
71	  }
72	
73	  if (input.inject?.length) {
74	    const injected: Message[] = [];
75	    for (const [messageIndex, message] of input.inject.entries()) {
76	      injected.push(
77	        makeMessage(
78	          ctx,
79	          message.role,
80	          await renderAuthored(
81	            { nodeId: ctx.node.id, boundary: 'subloop.input.inject.content', messageIndex },
82	            message.content,
83	            view,
84	          ),
85	          message.tags,
86	        ),
87	      );
88	    }
89	    seed.messages = [...(seed.messages ?? []), ...injected];
90	  }
91	  return seed;
92	}
93	
94	async function outputMapping(
95	  ctx: NodeContext<'subloop'>,
96	  child: ChildOutcome,
97	): Promise<PatchOperation[]> {
98	  const { output } = ctx.config;
99	  const parent = ctx.thread;
100	  const parentView = threadView(parent) as unknown as Record<string, unknown>;
101	  const childView = child.thread
102	    ? (threadView(child.thread) as unknown as Record<string, unknown>)
103	    : undefined;
104	  // A child that returned no output passes none: `result` stays absent, never `null` (docs/03).
105	  const result = child.result !== undefined ? { result: child.result } : {};
106	  const summary = toJson({
107	    status: child.status,
108	    outcome: child.outcome ?? null,
109	    ...result,
110	    childRunId: child.runId,
111	  });
112	  const patch: PatchOperation[] = [];
113	
114	  if (output.mode === 'custom') {
115	    const site = { nodeId: ctx.node.id, boundary: 'subloop.output.custom.patch' } as const;
116	    const value = await evaluateAuthored(site, output.custom?.patch ?? '[]', {
117	      parent: parentView,
118	      child: childView ?? null,
119	      ...result,
120	      outcome: child.outcome ?? null,
121	      status: child.status,
122	    });
123	    const checked = JsonPatchSchema.safeParse(value);
124	    if (!checked.success) throw authoredFailure(site, { kind: 'patch-shape' });
125	    try {
126	      assertMutablePatch(checked.data);
127	    } catch (error) {
128	      if (!(error instanceof MutationError)) throw error;
129	      throw authoredFailure(site, { kind: 'patch-region' });
130	    }
131	    patch.push(...checked.data);
132	    return patch;
133	  }
134	
135	  if (output.resultTo.lastOutput)
136	    patch.push(...outputPatch(parent, ctx.node.id, summary, ctx.services.now()));
137	
138	  // Variables are merged into one replacement so the merge strategy and the result variable compose.
139	  let vars: Record<string, JsonValue> = { ...parent.vars };
140	  let varsChanged = false;
141	
142	  if (output.mode === 'merge' && child.thread) {
143	    const childThread = child.thread;
144	    if (output.vars) {
145	      if (output.vars.strategy === 'explicit') {
146	        for (const [mapIndex, [name, expression]] of Object.entries(
147	          output.vars.map ?? {},
148	        ).entries()) {
149	          vars[name] = toJson(
150	            await evaluateAuthored(
151	              { nodeId: ctx.node.id, boundary: 'subloop.output.vars', mapIndex },
152	              expression,
153	              childView,
154	            ),
155	          );
156	        }
157	      } else if (output.vars.strategy === 'parent-wins') {
158	        vars = { ...childThread.vars, ...vars };
159	      } else {
160	        vars = { ...vars, ...childThread.vars };
161	      }
162	      varsChanged = true;
163	    }
164	    const messages = await selectMessages(
165	      childThread.messages,
166	      output.messages ?? 'none',
167	      childView ?? {},
168	      { nodeId: ctx.node.id, boundary: 'subloop.output.messages.where' },
169	    );
170	    for (const message of messages) patch.push(messagePatch(message));
171	    const artifacts = await selectCollection(
172	      childThread.artifacts,
173	      output.artifacts ?? 'none',
174	      childView ?? {},
175	      { nodeId: ctx.node.id, boundary: 'subloop.output.artifacts.where' },
176	    );
177	    for (const artifact of artifacts)
178	      patch.push({ op: 'add', path: '/artifacts/-', value: toJson(artifact) });
179	  }
180	  // The result variable is applied after any merge, so it holds exactly what the child returned:
181	  // a merged variable of the same name (the child's inherited copy, say) never overrides it.
182	  const resultVar = output.resultTo.var;
183	  if (resultVar && child.result !== undefined) {
184	    vars[resultVar] = child.result;
185	    varsChanged = true;
186	  } else if (resultVar && Object.hasOwn(vars, resultVar)) {
187	    // No output: the variable no longer holds a result (an earlier visit's, or a merged copy).
188	    vars = Object.fromEntries(Object.entries(vars).filter(([name]) => name !== resultVar));
189	    varsChanged = true;
190	  }
191	  if (varsChanged) patch.push({ op: 'replace', path: '/vars', value: toJson(vars) });
192	
193	  if (output.usage === 'roll-up' && child.thread) {
194	    patch.push({
195	      op: 'replace',
196	      path: '/counters/usage',
197	      value: toJson(addUsage(parent.counters.usage, child.thread.counters.usage)),
198	    });
199	  }
200	  return patch;
201	}
202	
203	export const subloopHandler: NodeHandler<'subloop'> = {
204	  kind: 'subloop',
205	  async execute(ctx) {
206	    const { config } = ctx;
207	    // The child this visit awaits: the child of its recorded park (woken or not), or the one this
208	    // visit's `child_run.started` names (the process died before the park was recorded), so a
209	    // second one is never started (docs/05, crash recovery).
210	    const awaited = ctx.previousWait?.childRunId ?? (await childOfThisVisit(ctx));
211	    if (awaited) {
212	      let child = await ctx.services.childOutcome(awaited);
213	      // This run failed with its child's resumable failure and was explicitly resumed: resume the
214	      // child in place, as resuming an inline failure re-executes the failed node (#251).
215	      if (child.failure?.resumable && failedSinceAwaiting(await ctx.services.events(), ctx.node.id))
216	        child = await ctx.services.resumeChild(awaited);
217	      // The parent continues only after its child has finished: an unfinished child (one resumed
218	      // after it notified, say) is awaited again rather than mapped.
219	      if (!isTerminal(child.status)) {
220	        return {
221	          kind: 'park',
222	          patch: [],
223	          wait: { nodeId: ctx.node.id, kind: 'child', childRunId: awaited },
224	        };
225	      }
226	      return finishWithChild(ctx, child);
227	    }
228	    const depth = await ctx.services.depth();
229	    const limit = config.depthLimitOverride ?? ctx.definition.settings.subloopDepthLimit;
230	    if (depth + 1 > limit) {
231	      throw new RunFailureError(
232	        'SUBLOOP_DEPTH_EXCEEDED',
233	        `subloop depth ${depth + 1} exceeds the limit ${limit}`,
234	        { nodeId: ctx.node.id, resumable: false },
235	      );
236	    }
237	    const seed = await buildSeed(ctx);
238	    const view = threadView(ctx.thread) as unknown as Record<string, unknown>;
239	    const triggerPayload = config.input.trigger
240	      ? toJson(
241	          await evaluateAuthored(
242	            { nodeId: ctx.node.id, boundary: 'subloop.input.trigger.payload' },
243	            config.input.trigger.payload,
244	            view,
245	          ),
246	        )
247	      : ctx.thread.invocation.trigger.payload;
248	    // The child and this visit's `child_run.started` are one commit (#320): a crash leaves both or
249	    // neither, so recovery finds this child above or starts the only one.
250	    const childRunId = await ctx.services.startChild({
251	      nodeId: ctx.node.id,
252	      loopId: config.loopRef.loopId,
253	      version: config.loopRef.version,
254	      seed,
255	      triggerPayload,
256	      depthLimit: limit,
257	    });
258	    return { kind: 'park', patch: [], wait: { nodeId: ctx.node.id, kind: 'child', childRunId } };
259	  },
260	};
261	
262	async function finishWithChild(
263	  ctx: NodeContext<'subloop'>,
264	  child: ChildOutcome,
265	): Promise<NodeResult> {
266	  const events = await ctx.services.events();
267	  // A wake durably names the observed child outcome before it can be consumed. A child retried
268	  // independently while this parent was interrupted needs a fresh park/wake for its new outcome.
269	  if (
270	    child.terminalSeq === undefined ||
271	    lastChildWakeSeq(events, child.runId) !== child.terminalSeq
272	  )
273	    return {
274	      kind: 'park',
275	      patch: [],
276	      wait: { nodeId: ctx.node.id, kind: 'child', childRunId: child.runId },
277	    };
278	  // The child's completion is written in the same append as this visit's own outcome: its
279	  // `node.finished`, its `run.failed` or its cancellation (#398). A process that dies first leaves
280	  // neither, so the re-executed visit records the completion exactly once, and a visit that never
281	  // durably reached an outcome never claims to have observed one.
282	  const completion: EventDraft = {
283	    type: 'child_run.finished',
284	    nodeId: ctx.node.id,
285	    childRunId: child.runId,
286	    status: child.status,
287	    ...(child.outcome ? { outcome: child.outcome } : {}),
288	  };
289	  const records = finishRecorded(events, child.runId, child.terminalSeq) ? [] : [completion];
290	  // Ordinary failure rules (#251): the child's execution error or cancellation is the parent's,
291	  // exactly as if the failing work had run inline. An authored outcome (Success, Failure or
292	  // Exhausted exit) is data for the output mapping.
293	  if (child.status === 'cancelled') throw new ChildCancelledError(child.runId, records);
294	  if (child.failure) {
295	    const { code, resumable, nodeId, script } = child.failure;
296	    const { message, details, diagnostics } = childFailureForPublication(child.failure);
297	    if (diagnostics.length) {
298	      ctx.ports.logger.error(
299	        {
300	          runId: ctx.run.id,
301	          nodeId: ctx.node.id,
302	          childRunId: child.runId,
303	          childNodeId: nodeId,
304	          diagnostics,
305	        },
306	        'subloop child failure contained internal diagnostics',
307	      );
308	    }
309	    const summary = `subloop child ${child.runId} failed: ${message}`;
310	    const options: RunFailureError['options'] = {
311	      nodeId: ctx.node.id,
312	      resumable,
313	      ...(script ? { script } : {}),
314	      details: {
315	        childRunId: child.runId,
316	        ...(nodeId ? { childNodeId: nodeId } : {}),
317	        ...(details !== undefined ? { childDetails: details } : {}),
318	      },
319	      records,
320	    };
321	    throw code === 'INTERNAL_ERROR'
322	      ? new InternalRunFailureError(summary, options)
323	      : new RunFailureError(code, summary, options);
324	  }
325	  let patch: NodeResult['patch'];
326	  try {
327	    patch = await outputMapping(ctx, child);
328	  } catch (error) {
329	    // The completion stands even when this run cannot map it; keep it with the failure, classified
330	    // exactly as the executor classifies an error a handler lets escape.
331	    if (error instanceof RunFailureError)
332	      throw new RunFailureError(error.code, error.message, {
333	        ...error.options,
334	        records: [...records, ...(error.options.records ?? [])],
335	      });
336	    ctx.ports.logger.error(
337	      {
338	        runId: ctx.run.id,
339	        nodeId: ctx.node.id,
340	        childRunId: child.runId,
341	        error: errorDiagnostic(error),
342	      },
343	      'subloop output mapping failed',
344	    );
345	    throw new InternalRunFailureError(INTERNAL_FAILURE_MESSAGE, {
346	      nodeId: ctx.node.id,
347	      records,
348	    });
349	  }
350	  return { kind: 'done', patch, route: 'out', records };
351	}
352	
353	/**
354	 * Whether this run failed after it parked on (or started) this node's child: it is executing
355	 * again, so it was explicitly resumed from that failure.
356	 */
357	function failedSinceAwaiting(events: readonly RunEvent[], nodeId: string): boolean {
358	  for (let i = events.length - 1; i >= 0; i -= 1) {
359	    const event = events[i] as RunEvent;
360	    if (event.type === 'run.failed') return true;
361	    if (
362	      (event.type === 'run.waiting' || event.type === 'child_run.started') &&
363	      event.nodeId === nodeId
364	    )
365	      return false;
366	  }
367	  return false;
368	}
369	
370	/** Outcome identity carried by an identity-bound child wake; the payload is ordinary JSON. */
371	function childWakeSeq(event: RunEvent, childRunId: string): number | undefined {
372	  if (event.type !== 'run.woken' || event.reason !== 'child') return undefined;
373	  const payload = event.payload;
374	  if (
375	    !payload ||
376	    typeof payload !== 'object' ||
377	    Array.isArray(payload) ||
378	    payload.childRunId !== childRunId
379	  )
380	    return undefined;
381	  return typeof payload.childFinishedSeq === 'number' ? payload.childFinishedSeq : undefined;
382	}
383	
384	function lastChildWakeSeq(events: readonly RunEvent[], childRunId: string): number | undefined {
385	  for (let index = events.length - 1; index >= 0; index -= 1) {
386	    const seq = childWakeSeq(events[index] as RunEvent, childRunId);
387	    if (seq !== undefined) return seq;
388	  }
389	  return undefined;
390	}
391	
392	/** A finish belongs to the durable child-outcome identity observed by its preceding child wake. */
393	function finishRecorded(
394	  events: readonly RunEvent[],
395	  childRunId: string,
396	  terminalSeq: number,
397	): boolean {
398	  let observed: number | undefined;
399	  for (const event of events) {
400	    const seq = childWakeSeq(event, childRunId);
401	    if (seq !== undefined) observed = seq;
402	    if (
403	      event.type === 'child_run.finished' &&
404	      event.childRunId === childRunId &&
405	      observed === terminalSeq
406	    )
407	      return true;
408	  }
409	  return false;
410	}
411	
412	/** The child this node started during its current, unfinished visit, from the run's log. */
413	async function childOfThisVisit(ctx: NodeContext<'subloop'>): Promise<string | undefined> {
414	  const events = await ctx.services.events();
415	  for (let i = events.length - 1; i >= 0; i -= 1) {
416	    const event = events[i] as RunEvent;
417	    if (event.type === 'node.finished' && event.nodeId === ctx.node.id) return undefined;
418	    if (event.type === 'child_run.started' && event.nodeId === ctx.node.id) return event.childRunId;
419	  }
420	  return undefined;
421	}
