1	import {
2	  DecisionEmissionSchema,
3	  LIMIT_REACHED_PORT_ID,
4	  type DecisionContext,
5	  type DecisionPayload,
6	  type JsonValue,
7	} from '@graphgoblin/contracts';
8	import { decisionPortId, decisionRouteDeclarations, threadView } from '@graphgoblin/domain';
9	import { RunFailureError } from '../errors.js';
10	import { renderAuthored } from '../authored-failure.js';
11	import type { NodeContext, NodeHandler } from '../handler.js';
12	import { pinnedBinding } from '../definition-pin.js';
13	import { evaluateClassifier, evaluateRoute } from '../primitive-evaluator.js';
14	import { outputPatch, selectMessages, toJson } from './common.js';
15	
16	async function decisionContext(
17	  ctx: NodeContext<'decision'>,
18	  context: DecisionContext,
19	): Promise<JsonValue> {
20	  const view = threadView(ctx.thread) as unknown as Record<string, unknown>;
21	  const messages = await selectMessages(ctx.thread.messages, context.messages, view, {
22	    nodeId: ctx.node.id,
23	    boundary: 'decision.context.messages.where',
24	  });
25	  const vars: Record<string, JsonValue> = {};
26	  for (const name of context.vars ?? Object.keys(ctx.thread.vars)) {
27	    if (name in ctx.thread.vars) vars[name] = ctx.thread.vars[name] as JsonValue;
28	  }
29	  return toJson({
30	    trigger: ctx.thread.invocation.trigger.payload,
31	    messages: messages.map((m) => ({ role: m.role, content: m.content })),
32	    vars,
33	    ...(context.includeLastOutput && ctx.thread.lastOutput
34	      ? { lastOutput: ctx.thread.lastOutput.value }
35	      : {}),
36	  });
37	}
38	
39	export const decisionHandler: NodeHandler<'decision'> = {
40	  kind: 'decision',
41	  async execute(ctx) {
42	    const config = ctx.config;
43	    const view = threadView(ctx.thread) as unknown as Record<string, unknown>;
44	    const common = {
45	      nodeId: ctx.node.id,
46	      ownerId: ctx.run.ownerId,
47	      signal: ctx.signal,
48	      ports: ctx.ports,
49	      resolveModel: (...args: Parameters<typeof ctx.services.resolveModel>) =>
50	        ctx.services.resolveModel(...args),
51	      structuredTimeoutMs: ctx.run.pinned.limits.structuredTimeoutMs,
52	      runId: ctx.run.id,
53	    };
54	    let payload: DecisionPayload;
55	    switch (config.kind) {
56	      case 'expression':
57	      case 'llm': {
58	        const result =
59	          config.kind === 'expression'
60	            ? await evaluateRoute({ ...common, config, expressionView: view })
61	            : await evaluateRoute({
62	                ...common,
63	                config,
64	                instructions: await renderAuthored(
65	                  { nodeId: ctx.node.id, boundary: 'decision.instructions' },
66	                  config.instructions,
67	                  view,
68	                ),
69	                context: await decisionContext(ctx, config.context),
70	              });
71	        if (result.observation.kind !== 'route')
72	          throw new Error('route evaluator returned a different observation');
73	        payload = { ...result, portId: result.observation.routeId };
74	        break;
75	      }
76	      case 'classifier': {
77	        const result = await evaluateClassifier({
78	          ...common,
79	          config,
80	          binding: pinnedBinding(ctx.run.pinned.classifiers, config.model),
81	          question: await renderAuthored(
82	            { nodeId: ctx.node.id, boundary: 'decision.question' },
83	            config.question,
84	            view,
85	          ),
86	          context: await decisionContext(ctx, config.context),
87	        });
88	        const answer =
89	          result.answer.type === 'noul'
90	            ? result.answer
91	            : {
92	                ...result.answer,
93	                probabilities: config.recordAlternatives ? result.answer.probabilities : null,
94	              };
95	        if (result.acceptance.status === 'rejected')
96	          throw new RunFailureError(
97	            result.acceptance.code,
98	            'Classifier confidence is below the authored minimum',
99	            {
100	              nodeId: ctx.node.id,
101	              resumable: false,
102	              details: {
103	                observation: { kind: 'classifier', answer },
104	                provenance: result.provenance,
105	                acceptance: result.acceptance,
106	              },
107	            },
108	          );
109	        payload = {
110	          observation: { kind: 'classifier', answer },
111	          provenance: result.provenance,
112	          portId: decisionPortId(config.answer, answer),
113	        };
114	        break;
115	      }
116	    }
117	    const repeat = decisionRouteDeclarations(config).find((route) => route.repeat);
118	    if (repeat) {
119	      const previousPasses = ctx.thread.gates[ctx.node.id]?.passes ?? 1;
120	      const maxPasses = config.maxPasses!;
121	      // Run time includes waits, pauses and recovery downtime, and is checked after evaluation.
122	      const elapsedSeconds = Math.max(
123	        0,
124	        (Date.parse(ctx.services.now()) - Date.parse(ctx.run.startedAt ?? ctx.run.createdAt)) /
125	          1000,
126	      );
127	      const limit =
128	        payload.portId !== repeat.id
129	          ? null
130	          : maxPasses !== null && previousPasses >= maxPasses
131	            ? 'max-passes'
132	            : config.maxRunTimeSeconds !== undefined && elapsedSeconds >= config.maxRunTimeSeconds
133	              ? 'max-run-time'
134	              : null;
135	      payload = {
136	        ...payload,
137	        portId: limit ? LIMIT_REACHED_PORT_ID : payload.portId,
138	        gate: {
139	          previousPasses,
140	          passes: previousPasses + (payload.portId === repeat.id && !limit ? 1 : 0),
141	          repeatRouteId: repeat.id,
142	          maxPasses,
143	          elapsedSeconds,
144	          limit,
145	          ...(config.maxRunTimeSeconds !== undefined
146	            ? { maxRunTimeSeconds: config.maxRunTimeSeconds }
147	            : {}),
148	        },
149	      };
150	    }
151	    const evidence = DecisionEmissionSchema.safeParse({ ...payload, diagnostics: [] });
152	    if (!evidence.success)
153	      throw new RunFailureError(
154	        'EVALUATION_INVALID_RESPONSE',
155	        'The evaluator returned evidence inconsistent with its kind',
156	        { nodeId: ctx.node.id, resumable: false },
157	      );
158	    return {
159	      kind: 'decision',
160	      evidence: evidence.data,
161	      patch: outputPatch(ctx.thread, ctx.node.id, toJson(payload), ctx.services.now()),
162	      route: payload.portId,
163	    };
164	  },
165	};
166

