1	import type { JsonPatch, PatchOperation } from '@graphgoblin/contracts';
2	import { MutationError, PatchError } from './errors.js';
3	import { getAtPointer, pointerStartsWith, updateAtPointer } from './pointer.js';
4	
5	/** Regions authored patches may mutate. Engine patches use unrestricted applyPatch instead. */
6	export const MUTABLE_REGIONS = [
7	  '/vars',
8	  '/messages',
9	  '/artifacts',
10	  '/outputs',
11	  '/lastOutput',
12	] as const;
13	
14	export function assertMutablePath(path: string, location: 'path' | 'from' = 'path'): void {
15	  if (!MUTABLE_REGIONS.some((region) => pointerStartsWith(path, region))) {
16	    throw new MutationError(
17	      `${location} "${path}" is not in a mutable region (${MUTABLE_REGIONS.join(', ')})`,
18	    );
19	  }
20	}
21	
22	/** Validate the entire authored patch before applying anything. Copy sources are read-only. */
23	export function assertMutablePatch(patch: JsonPatch): void {
24	  for (const op of patch) {
25	    if (op.op === 'test') continue;
