16	const cache = new Map<string, ValidateFunction>();
17	const CACHE_LIMIT = 256;
18	
19	/** One problem with a value, located: what a form needs to put the message beside its field. */
20	export interface SchemaIssue {
21	  /**
22	   * Where the problem is, as property names and array indexes from the root (JSON Pointer
23	   * segments, unescaped). A missing required property ends with that property's name.
24	   */
25	  path: string[];
26	  /** What is wrong there, without the path: "must be integer", "is required". */
27	  message: string;
28	}
29	
30	export interface SchemaValidation {
31	  ok: boolean;
32	  /** One line per problem, led by its JSON Pointer ("/n must be >= 1"). */
33	  errors: string[];
34	  /** The same problems, located (empty when `ok`). */
35	  issues: SchemaIssue[];
36	}
37	
38	/** Deterministic JSON serialisation with sorted object keys. */
39	export function stableStringify(value: unknown): string {
40	  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'undefined';
41	  if (Array.isArray(value)) return `[${value.map((v) => stableStringify(v)).join(',')}]`;
42	  const entries = Object.entries(value as Record<string, unknown>)
43	    .filter(([, v]) => v !== undefined)
44	    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
45	    .map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`);
46	  return `{${entries.join(',')}}`;
47	}
48	
49	function compileSchema(schema: JsonSchema): ValidateFunction {
50	  const key = stableStringify(schema);
51	  const hit = cache.get(key);
52	  if (hit) return hit;
53	  let compiled: ValidateFunction;
54	  try {
55	    // The validator retains schema data, so give it a snapshot of the cache key.
56	    compiled = ajv.compile(JSON.parse(key));
57	  } finally {
58	    // Compilation is synchronous. Clear root and nested registrations even when
59	    // compilation fails. Previously compiled validators keep their resolved refs.
60	    ajv.removeSchema();
61	  }
62	  if (cache.size >= CACHE_LIMIT) {
63	    const first = cache.keys().next().value;
64	    if (first !== undefined) cache.delete(first);
65	  }
66	  cache.set(key, compiled);
67	  return compiled;
68	}
69	
70	/** Validate a value against a JSON Schema. Compilation errors are reported as validation errors. */
71	export function validateJson(schema: JsonSchema, value: unknown): SchemaValidation {
72	  let validate: ValidateFunction;
73	  try {
74	    validate = compileSchema(schema);
75	  } catch (error) {
76	    const message = `invalid schema: ${error instanceof Error ? error.message : String(error)}`;
77	    return { ok: false, errors: [message], issues: [{ path: [], message }] };
78	  }
79	  const ok = validate(value);
80	  if (ok) return { ok: true, errors: [], issues: [] };
81	  const found = validate.errors ?? [];
82	  const errors = found.map((e) => `${e.instancePath || '/'} ${e.message ?? 'is invalid'}`.trim());
83	  return { ok: false, errors, issues: found.map(issueOf) };
84	}
85	
86	/** JSON Pointer segments, unescaped (`~1` is `/`, `~0` is `~`). */
87	function pointerSegments(pointer: string): string[] {
88	  if (pointer === '') return [];
89	  return pointer
90	    .slice(1)
91	    .split('/')
92	    .map((segment) => segment.replace(/~1/g, '/').replace(/~0/g, '~'));
93	}
94	
95	/** An Ajv error as a located issue; a missing property (`required`) is located at itself. */
96	function issueOf(error: ErrorObject): SchemaIssue {
97	  const path = pointerSegments(error.instancePath);
98	  const missing = (error.params as { missingProperty?: unknown }).missingProperty;
99	  if (typeof missing === 'string') return { path: [...path, missing], message: 'is required' };
100	  return { path, message: error.message ?? 'is invalid' };
101	}
102	
103	/** FNV-1a 64-bit hash of the stable serialisation, as 16 hex characters. Browser-safe. */
104	export function stableHash(value: unknown): string {
105	  const text = stableStringify(value);
106	  let hash = BigInt('0xcbf29ce484222325');
107	  const prime = BigInt('0x100000001b3');
108	  const mask = BigInt('0xffffffffffffffff');
109	  for (let i = 0; i < text.length; i += 1) {
110	    hash ^= BigInt(text.charCodeAt(i));
111	    hash = (hash * prime) & mask;
112	  }
113	  return hash.toString(16).padStart(16, '0');
114	}
