async function expressionValue(
  request: EvaluationRequest,
  source: string,
  view: unknown,
): Promise<unknown> {
  request.signal.throwIfAborted();
  try {
    const value: unknown = await evaluateExpression(source, view);
    request.signal.throwIfAborted();
    return value;
  } catch (error) {
    if (isAbortError(error) || request.signal.aborted) throw error;
